44	export async function listOrgsForUser(
45	  userId: UserId,
46	): Promise<readonly Organization[]> {
47	  const rows = getDb()
48	    .select({ org: organizations })
49	    .from(members)
50	    .innerJoin(organizations, eq(organizations.id, members.orgId))
51	    .where(and(eq(members.userId, userId), isNull(members.archivedAt)))
52	    .all();
53	
54	  return rows.map((row) => toOrganization(row.org));
55	}
