/**
 * A closed workspace resolves to `null` here, the same as a slug nobody ever
 * claimed — the `[orgSlug]` layout turns either case into the same 404, and
 * the slug itself stays reserved so a new organization asking for it gets a
 * suffixed variant instead of colliding.
 */
export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  const org = await orgRepo.findOrgBySlug(slug);
  if (org === null || org.archivedAt !== null) return null;
  return org;
}

