2	
3	/**
4	 * Creates an organization with the caller as owner.
5	 *
6	 * Owner D. There is no actor *before* the org exists, so this action resolves
7	 * the session principal first and only calls `getActor()` afterwards — against
8	 * the slug of the organization it just created — to confirm the owner
9	 * membership landed.
10	 *
11	 * Must call (do not reimplement): createOrganizationSchema, getActor,
12	 * toActionResult
13	 */
14	
15	import { UnauthorizedActionError } from "@/actions/_lib/action-errors";
16	import { getActor } from "@/lib/actor";
17	import { toActionResult } from "@/lib/errors";
18	import { getSessionPrincipal } from "@/lib/session";
19	import { createOrganizationSchema } from "@/schemas/organization";
20	import { createOrganization } from "@/server/services/organization-service";
21	import type { ActionResult } from "@/types/api";
22	import type { Organization } from "@/types/organization";
23	import { revalidatePath } from "next/cache";
24	
25	export async function createOrganizationAction(
26	  raw: unknown,
27	): Promise<ActionResult<Organization>> {
28	  const parsed = createOrganizationSchema.safeParse(raw);
29	  if (!parsed.success) {
30	    return toActionResult(parsed.error);
31	  }
32	
33	  try {
34	    const principal = await getSessionPrincipal();
35	    if (principal === null) {
36	      throw new UnauthorizedActionError();
37	    }
38	
39	    const organization = await createOrganization(principal.userId, parsed.data);
40	
41	    // The owner membership is written by the service; resolving the actor here
42	    // fails loudly if it was not, rather than leaving an org nobody can open.
43	    await getActor(organization.slug);
44	
45	    revalidatePath("/orgs");
46	    return { ok: true, data: organization, submittedAt: new Date().toISOString() };
47	  } catch (error) {
48	    return toActionResult(error);
49	  }
50	}
