});

describe("closing a workspace", () => {
  it("disappears from the member list and cannot be reopened", async () => {
    const tenant = await createTenant("close-visibility");

    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const orgs = await orgService.listOrganizationsForUser(tenant.userIds.owner);
    expect(orgs.find((o) => o.id === tenant.org.id)).toBeUndefined();

    await expect(orgService.resolveOrgBySlug(tenant.org.slug)).resolves.toBeNull();

    await expect(
      orgService.getOrganizationSummary(tenant.actors.owner, tenant.org.id),
    ).rejects.toMatchObject({ code: "not_found" });
  });

  it("refuses a second close as a conflict", async () => {
    const tenant = await createTenant("close-twice");

    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    await expect(
      orgService.deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("cancels the subscription immediately", async () => {
    const tenant = await createTenant("close-billing");

    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(sub?.status).toBe("canceled");
  });

  it("refuses an invitation acceptance after closing", async () => {
    const tenant = await createTenant("close-invite");
    const rawToken = "d".repeat(32);

    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "late@close-invite.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.admin,
      hashToken(rawToken),
    );

    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const newUser = await userRepo.insertUser({
      email: "late@close-invite.test",
      name: "Late",
      passwordHash: "seed",
    });

    await expect(
      invitationService.acceptInvitation(newUser.id, { token: rawToken }),
    ).rejects.toThrow(/closed/);
  });

  it("reserves the slug for reuse by a fresh workspace", async () => {
    const tenant = await createTenant("close-slug");

    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const reborn = await orgRepo.insertOrg(
      { name: "Reborn", slug: "close-slug", plan: "free" },
      tenant.userIds.owner,
    );

    expect(reborn.slug).not.toBe("close-slug");
    expect(reborn.id).not.toBe(tenant.org.id);
  });

  it("skips background jobs for a closed workspace", async () => {
    const tenant = await createTenant("close-jobs");

    const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const overdue = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { dueAt: "2020-01-01T00:00:00.000Z" }),
      tenant.userIds.owner,
      number,
    );

    const endpoint = await webhookRepo.insertEndpoint(
      { orgId: tenant.org.id, url: "https://example.test/hook", eventTypes: ["issue.created"] },
      "secret",
    );
    const delivery = await webhookRepo.enqueueDelivery(
      tenant.org.id,
      endpoint.id,
      "issue.created",
      "{}",
    );

    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const seen: string[] = [];
    const { subscribe } = await import("@/lib/event-bus");
    const off = subscribe("issue.overdue", (payload) => seen.push(payload.issueId));
    await runOverdueIssueJob(new Date("2026-06-01T00:00:00.000Z"));
    off();
    expect(seen).not.toContain(overdue.id);

    await runWebhookDeliveryJob(new Date());
    const deliveries = await webhookRepo.claimPendingDeliveries(25);
    expect(deliveries.find((d) => d.id === delivery.id)).toBeUndefined();

    const reindexResult = await runSearchReindexJob(tenant.org.id);
    expect(reindexResult.processed).toBe(0);

    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "growth", "monthly");
    // Force the subscription back to a trialing state that already expired,
    // bypassing the close flow's own cancellation, to prove the job itself
    // still skips a closed org rather than relying solely on that.
    const db = (await import("@/server/db")).getDb();
    const { subscriptions } = await import("@/server/db");
    const { eq } = await import("drizzle-orm");
    db.update(subscriptions)
      .set({ status: "trialing", currentPeriodEnd: "2020-01-01T00:00:00.000Z", plan: "growth" })
      .where(eq(subscriptions.orgId, tenant.org.id))
      .run();

    const trialResult = await runTrialExpiryJob(new Date("2026-06-01T00:00:00.000Z"));
    expect(trialResult.processed).toBe(0);
    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(sub?.plan).toBe("growth");
  });
});
